from taf.rfrl.procedures.resources.python.logger import log_input_and_output


class EngValue(object):
    FREQ_PARSER = [('GHz', 1E9), ('MHz', 1E6), ('kHz', 1E3), ('Hz', 1)]

    def __init__(self):
        """
        Main purpose is to provide mechanism for storing engineering variables like frequency in unified way.
        Parser could be easily extend for different type of units: V, A, kg, m if required.
        :raises Exception: when appropriate parser can't be found or value parsed
        """
        self.init_value = None
        self.value = None
        self.unit = None

    @log_input_and_output
    def set_value(self, init_value):
        """
        Public method for setting/resetting value to be parsed
        :param init_value: input value represented as string like 1.234GHz
        :type init_value: str
        """
        self.init_value = str(init_value)
        self.value = None
        self.unit = None
        return

    @log_input_and_output
    def get_base_value(self):
        """
        Public method used for collecting value expressed in base unit, like frequency in Hz
        :return: value
        :rtype int
        """
        if self.value is None or self.unit is None:
            self._parse()

        return self.value

    @log_input_and_output
    def get_base_unit(self):
        """
        Public method used for collecting base unit
        :return: base unit
        :rtype str
        """
        if self.value is None or self.unit is None:
            self._parse()
        return self.unit

    @log_input_and_output
    def is_frequency(self):
        """
        Public method used for checking whether value could be parsed as frequency
        :return: is frequency
        :rtype bool
        """
        if self.init_value is None:
            raise Exception('Value not set - it need to be initialized before parsing')

        for unit, multiply in self.FREQ_PARSER:
            if unit.lower() in self.init_value.lower():
                return True

        return False

    @log_input_and_output
    def _parse(self):
        if self.init_value is None:
            raise Exception('Value not set - it need to be initialized before parsing')

        if self._parse_as_frequency():
            return

        raise Exception('Unknown value format: {} - appropriate parser cannot be found'.format(self.init_value))

    @log_input_and_output
    def _parse_as_frequency(self):
        if self.init_value is None:
            raise Exception('Value not set - it need to be initialized before parsing')

        for unit, multiply in self.FREQ_PARSER:
            if unit.lower() in self.init_value.lower():
                try:
                    self.value = int(float(self.init_value.lower().replace(unit.lower(), '').strip()) * multiply)
                    self.unit, _ = self.FREQ_PARSER[-1]
                except Exception:
                    raise Exception('Failed while trying to parse value as frequency')
                return True

        return False
